#!/usr/bin/env python3
"""queue.py - the Optimizer's maintenance queue, GENERATED by checks (excerpt of the production fila.py).

Why: a hand-written to-do list of "things to fix in the agents" grew to ~35 open items, 16 of which were
already fixed. Here the queue is reconciled against the real state on every run (level-triggered, like a
Kubernetes controller): if a check no longer reproduces a finding, the item CLOSES BY ITSELF. Each item
keeps the date it was first seen, so old problems are visible.

The production version runs ~10 checks (broken paths in docs, stale docs, skill pointer vs source, retired
terms still in use, pending items that need the human but have no task, ...). This excerpt keeps the
reconciliation engine and one structural check, so it runs standalone against examples/sample_system/.

Usage:  python src/optimizer/queue.py <root> [--state state.json] [--dry]
Exit:   0 = ran (findings are not errors) - 2 = usage error
"""

import json
import os
import re
import sys
from datetime import date

LIMIT_CLAUDE_MD = 200  # lines - official guidance: keep CLAUDE.md under ~200 lines
MANIFEST_FIELDS = ("Purpose", "Autonomy", "Surface", "Cadence", "Out of scope")


def item(check, target, detail, sev, sub=""):
    """One finding. `sub` tells apart different findings of the same check on the same target."""
    return {"check": check, "target": target, "detail": detail, "sev": sev, "sub": sub}


def agents(root):
    base = os.path.join(root, "agents")
    return sorted(
        os.path.join(base, n)
        for n in os.listdir(base)
        if re.match(r"^\d\d-agent-", n) and os.path.isdir(os.path.join(base, n))
    )


def check_structure(root):
    """Every agent folder has a CLAUDE.md (its runbook) with a complete manifest, under the size limit."""
    out = []
    for a in agents(root):
        rel = os.path.relpath(a, root).replace("\\", "/")
        p = os.path.join(a, "CLAUDE.md")
        if not os.path.exists(p):
            out.append(item("manifest", rel, "no CLAUDE.md", "high", sub="missing"))
            continue
        with open(p, encoding="utf-8") as f:
            text = f.read()
        lines = text.splitlines()
        if len(lines) > LIMIT_CLAUDE_MD:
            out.append(
                item("size", f"{rel}/CLAUDE.md", f"{len(lines)} lines > {LIMIT_CLAUDE_MD}", "medium", sub="lines")
            )
        section = text.split("## Manifest", 1)[1].split("\n## ", 1)[0] if "## Manifest" in text else ""
        missing = [f for f in MANIFEST_FIELDS if f"**{f}" not in section]
        if missing:
            out.append(item("manifest", f"{rel}/CLAUDE.md", "missing: " + ", ".join(missing), "medium", sub="fields"))
    return out


def key(i):
    """Stable identity of a finding across runs."""
    return f"{i['check']}|{i['sub']}|{i['target']}"


def reconcile(items, state, today):
    """Return (new_state, new_keys, closed_keys). A finding that disappeared from the checks is closed."""
    current = {key(i): i for i in items}
    new = [k for k in current if k not in state]
    closed = [k for k in state if k not in current]
    new_state = {k: {"since": state.get(k, {}).get("since", today.isoformat())} for k in current}
    return new_state, new, closed


def render(items, state, new, closed, today):
    order = {"high": 0, "medium": 1, "low": 2}
    out = [
        f"# Optimizer queue - GENERATED on {today.isoformat()} (do not edit by hand)",
        "",
        f"Open: **{len(items)}** - new: {len(new)} - closed by themselves (check passed): {len(closed)}",
        "",
        "| sev | check | target | detail | since |",
        "|---|---|---|---|---|",
    ]
    for i in sorted(items, key=lambda i: (order.get(i["sev"], 3), i["check"], i["target"])):
        out.append(f"| {i['sev']} | {i['check']} | {i['target']} | {i['detail']} | {state[key(i)]['since']} |")
    if closed:
        out += ["", "## Closed this run"] + [f"- {k}" for k in closed]
    return "\n".join(out) + "\n"


def main(argv):
    args = [a for a in argv if not a.startswith("--")]
    if not args:
        print(__doc__)
        return 2
    root = os.path.abspath(args[0])
    state_path = argv[argv.index("--state") + 1] if "--state" in argv else os.path.join(root, "queue-state.json")
    today = date.today()
    items = check_structure(root)
    state = {}
    if os.path.exists(state_path):
        with open(state_path, encoding="utf-8") as f:
            state = json.load(f)
    state, new, closed = reconcile(items, state, today)
    print(render(items, state, new, closed, today))
    if "--dry" not in argv:
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=1)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
